#[uses(input_ok, fits, height_ok, loop_inv)]
fn solve(n: i64) -> (r: i64)
    requires input_ok(n),
    ensures height_ok(n, r),
{
    let mut h: i64 = 1;
    while h < 8 && (h + 1) * (h + 2) * (h + 3) / 6 <= n
        invariant loop_inv(n, h), input_ok(n),
        decreases 8 - h,
    {
        h = h + 1;
    }
    h
}

