spec fn is_min_value(n: i64, k: i64, r: i64) -> bool {
    if n % k <= k - n % k { r == n % k } else { r == k - n % k }
}

spec fn in_mod_range(k: i64, r: i64) -> bool { 0 <= r && r < k }

#[effects(pure)]
#[uses(valid_input, is_min_value, in_mod_range)]
fn solve(n: i64, k: i64) -> (r: i64)
    requires valid_input(n, k),
    ensures is_min_value(n, k, r), in_mod_range(k, r),
{
    let m: i64 = n % k;
