spec fn is_boring(x: i64) -> bool {
    (1 <= x && x <= 9)
    || (11 <= x && x <= 99 && x % 11 == 0)
    || (111 <= x && x <= 999 && x % 111 == 0)
    || (1111 <= x && x <= 9999 && x % 1111 == 0)
}

spec fn digit_of(x: i64) -> i64 {
    if x <= 9 { x } else if x <= 99 { x / 11 } else if x <= 999 { x / 111 } else { x / 1111 }
}

spec fn len_of(x: i64) -> i64 {
    if x <= 9 { 1 } else if x <= 99 { 2 } else if x <= 999 { 3 } else { 4 }
}

#[uses(digit_of, len_of)]
spec fn keys_ok(x: i64, r: i64) -> bool {
    r >= 0 && r == 10 * (digit_of(x) - 1) + len_of(x) * (len_of(x) + 1) / 2
}

#[effects(pure)]
#[uses(is_boring, keys_ok, digit_of, len_of)]
fn solve(x: i64) -> (r: i64)
    requires is_boring(x),
    ensures keys_ok(x, r),
{
    let d: i64 = if x <= 9 { x } else if x <= 99 { x / 11 } else if x <= 999 { x / 111 } else { x / 1111 };
    let l: i64 = if x <= 9 { 1 } else if x <= 99 { 2 } else if x <= 999 { 3 } else { 4 };
    10 * (d - 1) + l * (l + 1) / 2
}

