}

spec fn at_most_len(v: &[i64], r: usize) -> bool { r <= v.len() }

spec fn none_zero_before(v: &[i64], r: usize) -> bool {
    forall|i: usize| i < r && i < v.len() ==> #[trigger] v[i] != 0
}

spec fn zero_at_unless_len(v: &[i64], r: usize) -> bool {
    r == v.len() || (r < v.len() && v[r] == 0)
}

#[effects(pure)]
#[uses(at_most_len, none_zero_before, zero_at_unless_len)]
fn mfirst_cero(v: &[i64]) -> (r: usize)
    ensures at_most_len(v, r),
    ensures none_zero_before(v, r),
    ensures zero_at_unless_len(v, r),
{
    let mut i: usize = 0;
    while i < v.len() && v[i] != 0
        invariant at_most_len(v, i),
        invariant none_zero_before(v, i),
        decreases v.len() - i,
    {
        i = i + 1;
    }
    i
}

