spec fn valid_input(nums: &[i64]) -> bool {
    1 <= nums.len() && nums.len() <= 2500
        && (forall|k: usize| k < nums.len() ==> -10000 <= #[trigger] nums[k] && nums[k] <= 10000)
}

spec fn at_least_one(r: i64) -> bool { r >= 1 }

#[effects(pure)]
#[uses(valid_input, at_least_one)]
fn longest_increasing_subsequence(nums: &[i64]) -> (r: i64)
    requires valid_input(nums),
    ensures at_least_one(r),
{
    let n: usize = nums.len();
    let mut dp: [i64; 2500] = [0; 2500];
    let mut best: i64 = 1;
    let mut i: usize = 0;
    while i < n
        invariant
            n == nums.len(),
            n <= 2500,
            i <= n,
            best >= 1,
            forall|k: usize| k < i ==> 1 <= #[trigger] dp[k] && dp[k] <= k + 1,
        decreases n - i,
    {
        let mut cur: i64 = 1;
        let mut j: usize = 0;
        while j < i
            invariant
                n == nums.len(),
                n <= 2500,
                i < n,
                j <= i,
                1 <= cur,
                cur <= j + 1,
                forall|k: usize| k < i ==> 1 <= #[trigger] dp[k] && dp[k] <= k + 1,
            decreases i - j,
        {
            if nums[j] < nums[i] && dp[j] + 1 > cur {
                cur = dp[j] + 1;
            }
            j = j + 1;
        }
        dp[i] = cur;
        if cur > best {
            best = cur;
        }
        i = i + 1;
    }
    best
}

