spec fn is_elem(lst: &[i64], r: i64) -> bool {
    exists|i: usize| i < lst.len() && #[trigger] lst[i] == r
}

spec fn is_upper(lst: &[i64], r: i64) -> bool {
    forall|i: usize| i < lst.len() ==> #[trigger] lst[i] <= r
}

spec fn prefix_upper(lst: &[i64], k: usize, r: i64) -> bool {
    forall|i: usize| i < k ==> #[trigger] lst[i] <= r
}

