    j < lst.len() && lst[j] == r
}

spec fn within(lst: &[i64], k: usize) -> bool {
    1 <= k && k <= lst.len()
}

#[effects(pure)]
#[uses(non_empty, is_elem, is_upper, prefix_upper, at, within)]
fn max_of_list(lst: &[i64]) -> (r: i64)
    requires non_empty(lst),
    ensures is_elem(lst, r), is_upper(lst, r),
{
    let mut m: i64 = lst[0];
    let mut j: usize = 0;
    let mut k: usize = 1;
    while k < lst.len()
        invariant within(lst, k), at(lst, j, m), prefix_upper(lst, k, m),
        decreases lst.len() - k,
    {
        if lst[k] > m {
            m = lst[k];
            j = k;
        }
        k = k + 1;
    }
    m
}

